mapper.select:
SELECT id, subdivision_code AS subdivisionCode, country_code AS countryCode,
    parent_subdivision_code AS parentSubdivisionCode, category, name, local_name AS localName, status,
    version, create_time AS createTime, update_time AS updateTime
FROM t_ref_country_subdivision

    AND country_code = #{countryCode}
    AND status = #{status}

        AND subdivision_code IN
        #{code}


ORDER BY subdivision_code
